28	const __filename = fileURLToPath(import.meta.url);
29	const __dirname = path.dirname(__filename);
30	
31	// 1. Installation directory defaults
32	loadDotenv({ path: path.resolve(__dirname, "../.env") });
33	// 2. Global user config (~/.config/nexus/config.env)
34	const globalConfig = path.join(os.homedir(), ".config/nexus/config.env");
35	if (fs.existsSync(globalConfig)) {
36	  loadDotenv({ path: globalConfig, override: true });
37	}
38	// 3. Current working directory overrides (skipped when cwd is the install directory: that file is the
39	//    shipped default already applied in step 1 and must not outrank the user's global config)
40	const cwdEnv = path.resolve(process.cwd(), ".env");
41	if (cwdEnv !== path.resolve(__dirname, "../.env")) {
42	  loadDotenv({ path: cwdEnv, override: true });
43	}
