45	const program = new Command();
46	
47	program
48	  .name("harness")
49	  .description("Nexus Code - Custom Autonomous Coding Harness for Local AI (LM Studio / vLLM)")
50	  .version("1.2.1");
51	
52	function buildConfig(options: any): HarnessConfig {
53	  const endpoint = options.endpoint || process.env.LOCAL_LLM_ENDPOINT || "http://localhost:1234/v1";
54	  const model = options.model || process.env.LOCAL_LLM_MODEL || "local-model";
55	  const apiKey = options.apiKey || process.env.LOCAL_LLM_API_KEY || readLatestAuthToken() || "local";
56	  const workspace = options.workspace ? path.resolve(options.workspace) : process.cwd();
57	  const maxSteps = options.maxSteps ? parseInt(options.maxSteps, 10) : 30;
58	  const temperature = options.temperature ? parseFloat(options.temperature) : 0.2;
59	  const shell = options.shell || process.env.LOCAL_HARNESS_SHELL || "bash";
60	  const dryRun = Boolean(options.dryRun);
61	  const readOnly = Boolean(options.readOnly);
62	  const sandbox = options.sandbox ? (typeof options.sandbox === "string" ? options.sandbox : true) : undefined;
63	  const fallbackEndpoints = options.fallback ? options.fallback.split(",").map((s: string) => s.trim()) : undefined;
64	  const contextLimit = options.contextLimit ? parseInt(options.contextLimit, 10) : undefined;
65	  const worktree = Boolean(options.worktree);
66	  const authoritativeVerifierCommand = options.authoritativeVerifier;
67	  const recordFlight = Boolean(options.recordFlight || options.flight);
68	  const plannerModel = options.plannerModel || process.env.PLANNER_LLM_MODEL;
69	  const plannerEndpoint = options.plannerEndpoint || process.env.PLANNER_LLM_ENDPOINT;
70	  const coderModel = options.coderModel || process.env.CODER_LLM_MODEL;
71	  const coderEndpoint = options.coderEndpoint || process.env.CODER_LLM_ENDPOINT;
72	  const tdd = Boolean(options.tdd);
73	  const taskClass = process.env.NEXUS_TASK_CLASS || undefined;
74	  const plannerTaskClass = process.env.PLANNER_TASK_CLASS || undefined;
75	  return {
76	    taskClass,
77	    plannerTaskClass,
78	    endpoint,
79	    model,
80	    apiKey,
81	    workspace,
82	    maxSteps,
83	    temperature,
84	    shell,
85	    dryRun,
86	    readOnly,
87	    sandbox,
88	    fallbackEndpoints,
89	    contextLimit,
90	    worktree,
91	    authoritativeVerifierCommand,
92	    recordFlight,
93	    plannerModel,
94	    plannerEndpoint,
95	    coderModel,
96	    coderEndpoint,
97	    tdd,
98	  };
99	}
