101	program
102	  .command("repl")
103	  .description("Start interactive coding session (REPL / TUI)")
104	  .option("-e, --endpoint <url>", "Local LLM endpoint (default: $LOCAL_LLM_ENDPOINT)")
105	  .option("-m, --model <name>", "Model name identifier (default: active model in vLLM)")
106	  .option("-w, --workspace <path>", "Workspace directory (default: current directory)")
107	  .option("-s, --max-steps <number>", "Maximum steps per turn (default: 30)")
108	  .option("-t, --temperature <number>", "Model temperature (default: 0.2)")
109	  .option("--shell <type>", "Linux shell to use: bash, zsh, or sh (default: bash)", "bash")
110	  .option("--fallback <urls>", "Comma-separated fallback LLM endpoints if primary is unavailable")
111	  .option("--context-limit <tokens>", "Model context window limit in tokens (default: 65536)")
112	  .option("--dry-run", "Simulate file modifications without writing changes to disk")
113	  .option("--read-only", "Reject all mutating tool executions and commands")
114	  .option("--sandbox [mode]", "Isolate command execution using bubblewrap (bwrap) or Docker (default: auto)")
115	  .option("--worktree", "Isolate execution inside an ephemeral git worktree under .nexus/worktrees/<task-id>")
116	  .option("--authoritative-verifier <command>", "Trusted command whose successful exit may authorize automatic worktree merge")
117	  .option("--record-flight", "Record execution into an append-only deterministic .flightlog")
118	  .option("--planner-model <name>", "Deep reasoning model for architecture planning (o3, R1, Sonnet)")
119	  .option("--planner-endpoint <url>", "Dedicated inference endpoint for planner model")
120	  .option("--coder-model <name>", "High-throughput model for surgical code implementation (Qwen 2.5 Coder)")
121	  .option("--coder-endpoint <url>", "Dedicated inference endpoint for coder model")
122	  .option("--approve", "Require human approval before destructive actions (edits, shell commands)")
123	  .option("-r, --resume [id]", "Resume previous session (defaults to latest if id omitted)")
124	  .action(async (options: any) => {
125	    const config = buildConfig(options);
126	    if (config.model === "local-model") {
127	      try {
128	        const client = new LocalLlmClient(config);
129	        const models = await client.listModels();
130	        if (models.length > 0) {
131	          config.model = models[0];
132	        }
133	      } catch {
134	        // Fallback
135	      }
136	    }
137	    const resumeId = typeof options.resume === "string" ? options.resume : options.resume ? "latest" : undefined;
138	    const app = new ApplicationCore(config);
139	    const repl = new InteractiveRepl(app, !options.approve, resumeId);
140	    await repl.start();
141	  });
