143	program
144	  .command("run")
145	  .description("Run an autonomous coding task")
146	  .argument("<prompt...>", "The coding instructions / task prompt")
147	  .option("-e, --endpoint <url>", "Local LLM endpoint (default: http://localhost:1234/v1 or $LOCAL_LLM_ENDPOINT)")
148	  .option("-m, --model <name>", "Model name identifier (default: active model in LM Studio/vLLM)")
149	  .option("-w, --workspace <path>", "Workspace directory to inspect and modify (default: current directory)")
150	  .option("-s, --max-steps <number>", "Maximum autonomous agent steps", "30")
151	  .option("-t, --temperature <number>", "Model temperature", "0.2")
152	  .option("--shell <type>", "Linux shell to use: bash, zsh, or sh (default: bash or $LOCAL_HARNESS_SHELL)", "bash")
153	  .option("--fallback <urls>", "Comma-separated fallback LLM endpoints if primary is unavailable")
154	  .option("--context-limit <tokens>", "Model context window limit in tokens (default: 65536)")
155	  .option("--dry-run", "Simulate file modifications without writing changes to disk")
156	  .option("--read-only", "Reject all mutating tool executions and commands")
157	  .option("--sandbox [mode]", "Isolate command execution using bubblewrap (bwrap) or Docker (default: auto)")
158	  .option("--worktree", "Isolate execution inside an ephemeral git worktree under .nexus/worktrees/<task-id>")
159	  .option("--authoritative-verifier <command>", "Trusted command whose successful exit may authorize automatic worktree merge")
160	  .option("--record-flight", "Record execution into an append-only deterministic .flightlog")
161	  .option("--planner-model <name>", "Deep reasoning model for architecture planning (o3, R1, Sonnet)")
162	  .option("--planner-endpoint <url>", "Dedicated inference endpoint for planner model")
163	  .option("--coder-model <name>", "High-throughput model for surgical code implementation (Qwen 2.5 Coder)")
164	  .option("--coder-endpoint <url>", "Dedicated inference endpoint for coder model")
165	  .option("--tdd", "Enforce strict RED-GREEN-REFACTOR Test-Driven Development protocol")
166	  .option("-j, --json", "Output machine-readable JSON structured result (UI-002, UI-003)")
167	  .option("-r, --resume [id]", "Resume previous session or task state")
168	  .action(async (promptParts: string[], options: any) => {
169	    const prompt = promptParts.join(" ");
170	    const config = buildConfig(options);
171	    const isJson = Boolean(options.json);
172	
173	    // Auto-detect loaded model if model is 'local-model'
174	    if (config.model === "local-model") {
175	      try {
176	        const client = new LocalLlmClient(config);
177	        const models = await client.listModels();
178	        if (models.length > 0) {
179	          config.model = models[0];
180	          if (!isJson) {
181	            console.log(pc.dim(`🔍 Auto-detected active model: ${pc.bold(config.model)}`));
182	          }
183	        }
184	      } catch {
185	        // Fallback to default
186	      }
187	    }
188	
189	    const app = new ApplicationCore(config);
190	    const resumeTaskId = typeof options.resume === "string" ? options.resume : options.resume ? "latest" : undefined;
191	
192	    try {
193	      const result = await app.runTask(prompt, {
194	        json: isJson,
195	        resumeTaskId,
196	      });
197	
198	      if (isJson) {
199	        console.log(JSON.stringify(result, null, 2));
200	      }
201	
202	      app.shutdown();
203	      process.exit(result.success ? 0 : 1);
204	    } catch (err: any) {
205	      if (isJson) {
206	        console.log(JSON.stringify({
207	          taskId: app.getTaskId(),
208	          success: false,
209	          status: "failed",
210	          prompt,
211	          output: "",
212	          plan: [],
213	          milestones: [],
214	          validationReceipts: [],
215	          tokenStats: { prompt: 0, completion: 0, total: 0 },
216	          durationMs: 0,
217	          error: err.message,
218	        }, null, 2));
219	      } else {
220	        console.error(pc.red(`\nTask failed: ${err.message}`));
221	      }
222	      app.shutdown();
223	      process.exit(1);
224	    }
225	  });
