413	program
414	  .command("audit")
415	  .description("Inspect tool execution audit log and execution metrics")
416	  .option("-n, --limit <number>", "Number of recent records to display", "25")
417	  .option("-t, --tool <name>", "Filter by tool name")
418	  .option("--errors", "Show only failed executions")
419	  .action((options: any) => {
420	    const auditFile = path.join(os.homedir(), ".nexus", "audit.log");
421	    if (!fs.existsSync(auditFile)) {
422	      console.log(pc.yellow("\nNo audit records found in ~/.nexus/audit.log\n"));
423	      return;
424	    }
425	    const raw = fs.readFileSync(auditFile, "utf-8");
426	    let records = raw.trim().split("\n").filter(Boolean).map((l) => {
427	      try { return JSON.parse(l); } catch { return null; }
428	    }).filter(Boolean);
429	
430	    if (options.tool) {
431	      records = records.filter((r) => r.tool === options.tool);
432	    }
433	    if (options.errors) {
434	      records = records.filter((r) => !r.success);
435	    }
436	
437	    const limit = parseInt(options.limit, 10) || 25;
438	    const slice = records.slice(-limit);
439	
440	    if (slice.length === 0) {
441	      console.log(pc.yellow("\nNo matching audit records found.\n"));
442	      return;
443	    }
444	
445	    console.log(pc.bold(pc.cyan(`\n=== Nexus Code Tool Execution Audit Log (${slice.length} entries) ===\n`)));
446	    for (const r of slice) {
447	      const status = r.success ? pc.green("PASS") : pc.red("FAIL");
448	      const time = pc.gray(r.timestamp?.slice(0, 19).replace("T", " ") || "");
449	      const dur = pc.yellow(`${r.duration_ms || 0}ms`.padStart(6));
450	      const tool = pc.bold(pc.cyan((r.tool || "").padEnd(16)));
451	      console.log(`${time} | ${status} | ${tool} | ${dur}`);
452	      if (r.error) {
453	        console.log(`  ${pc.red("└─ Error:")} ${r.error}`);
454	      }
455	    }
456	    console.log();
457	  });
