133	    const taskId = this.agent.getTaskId();
134	    if (this.stateManager.hasTaskState(taskId)) {
135	      try {
136	        const state = this.stateManager.loadTaskState(taskId);
137	        if (!state.candidateId && state.validationReceipts && state.validationReceipts.length > 0) {
