162	   * Executes a task through the unified execution spine and durable state lifecycle (UI-001, UI-002, UI-003).
163	   */
164	  public async runTask(prompt: string, options: RunTaskOptions = {}): Promise<TaskExecutionResult> {
165	    const startTime = Date.now();
166	    const taskId = this.agent.getTaskId();
167	
168	    if (options.resumeTaskId) {
169	      await this.recoverTask(options.resumeTaskId);
170	    }
171	
172	    this.emit("task:start", {
173	      taskId,
174	      prompt,
175	      timestamp: new Date().toISOString(),
176	    });
177	
178	    const capturedLogs: string[] = [];
179	    const shouldCapture = Boolean(options.json || options.quiet);
180	
181	    // Intercept stdout/console when machine-readable JSON is requested
182	    const originalLog = console.log;
183	    const originalWarn = console.warn;
184	    const originalError = console.error;
185	    const originalStdoutWrite = process.stdout.write.bind(process.stdout);
186	
187	    if (shouldCapture) {
188	      console.log = (...args: any[]) => {
189	        capturedLogs.push(args.map((a) => (typeof a === "string" ? a : JSON.stringify(a))).join(" "));
