35	function parsePatchHunks(patch: string): { fileHeader: string; hunks: PatchHunk[] } {
36	  const lines = patch.split("\n");
37	  const fileHeaderLines: string[] = [];
38	  const hunks: PatchHunk[] = [];
39	  let currentHunk: PatchHunk | null = null;
40	
41	  for (const line of lines) {
42	    if (line.startsWith("@@")) {
43	      if (currentHunk) {
44	        hunks.push(currentHunk);
45	      }
46	      currentHunk = { header: line, lines: [] };
47	    } else if (currentHunk) {
48	      currentHunk.lines.push(line);
49	    } else {
50	      fileHeaderLines.push(line);
51	    }
52	  }
53	  if (currentHunk) {
54	    hunks.push(currentHunk);
55	  }
56	
57	  return { fileHeader: fileHeaderLines.join("\n"), hunks };
58	}
