1812	  async runTurn(taskPrompt: string | any[], onConfirm?: ConfirmHandler): Promise<void> {
1813	    // The REPL calls runTurn directly. Route worktree-enabled turns through the
1814	    // same establishment and resolution boundary as one-shot `run` tasks.
1815	    if (this.config.worktree && this.activeWorktree && !this.worktreeRunTurnAuthorized) {
1816	      throw new Error(`Cannot start a new task: unresolved worktree ${this.activeWorktree.taskId}; merge or discard it first.`);
1817	    }
1818	    if (this.config.worktree && !this.worktreeRunTurnAuthorized) {
1819	      await this.run(taskPrompt, onConfirm);
1820	      return;
1821	    }
1822	    await this.initExtensibility();
1823	    const promptText = typeof taskPrompt === "string" ? taskPrompt : "[Multi-modal Vision Input]";
1824	    await this.pluginManager.notifyTurnStart(promptText, this.config.workspace);
1825	
1826	    if (this.flightRecorder) {
1827	      if (!this.flightRecorder.isSessionActive()) {
1828	        this.flightRecorder.startSession({
1829	          model: this.config.model,
1830	          endpoint: this.config.endpoint,
1831	          taskPrompt: promptText,
1832	        });
1833	      }
1834	      this.flightRecorder.recordTurnStart(1, promptText);
1835	    }
1836	
1837	    // Dynamic runtime state injected into turn-level context without invalidating system prompt prefix cache
1838	    const gitInfo = getGitInfo(this.config.workspace);
1839	    let runtimeContext = "";
1840	    if (gitInfo.isRepo) {
1841	      runtimeContext += `\n[Git Status: ${gitInfo.branch} (${gitInfo.dirtyCount} uncommitted dirty files)]`;
1842	    }
1843	    if (this.activePlan && this.activePlan.length > 0) {
1844	      runtimeContext += `\n[Active Plan: ${this.activePlan.map((p, i) => `${i + 1}. [${p.status}] ${p.name}`).join(" -> ")}]`;
1845	    }
1846	
