8	
9	/**
10	 * Full-Screen Terminal User Interface (TUI) Dashboard (Candidate #19, UI-001, UI-004, UI-005)
11	 * Features alternate screen buffer mode, split-pane dashboard, and real-time state visualization
12	 * projected directly from the shared ApplicationCore model.
13	 */
14	export class TerminalDashboard {
15	  private app?: ApplicationCore;
16	  private agent: AutonomousAgent;
17	  private config: HarnessConfig;
18	  private themeManager: ThemeManager;
19	
20	  constructor(
21	    target: ApplicationCore | AutonomousAgent,
22	    config?: HarnessConfig,
23	    themeManager?: ThemeManager
24	  ) {
25	    if ("getAgent" in target && typeof (target as any).getAgent === "function") {
26	      this.app = target as ApplicationCore;
27	      this.agent = this.app.getAgent();
28	      this.config = config || this.app.getConfig();
29	    } else {
30	      this.agent = target as AutonomousAgent;
31	      this.config = config || this.agent.getConfig();
32	    }
33	    this.themeManager = themeManager || new ThemeManager();
34	  }
35	
36	  /**
37	   * Render a snapshot of the TUI dashboard layout into a string
38	   */
39	  public renderSnapshot(width: number = 100, height: number = 28): string {
40	    const termWidth = Math.max(80, width);
41	    const colLeftWidth = Math.floor(termWidth * 0.54);
42	    const colRightWidth = termWidth - colLeftWidth - 3;
43	    const scheme = this.themeManager.getScheme();
44	
45	    const lines: string[] = [];
46	
47	    // 1. Header Banner
48	    const title = "⚡ NEXUS CODE FULL-SCREEN TUI DASHBOARD";
49	    const meta = `Model: ${this.config.model} │ Workspace: ${path.basename(this.config.workspace || process.cwd())}`;
50	    const topBar = "╔" + "═".repeat(termWidth - 2) + "╗";
51	    const botBar = "╚" + "═".repeat(termWidth - 2) + "╝";
52	
53	    lines.push(scheme.primary(topBar));
54	    const headerContent = `  ${pc.bold(title)}   ${pc.dim(meta)}`;
55	    const headerPadded = headerContent + " ".repeat(Math.max(0, termWidth - 2 - this.stripAnsi(headerContent).length));
56	    lines.push(scheme.primary("║") + headerPadded + scheme.primary("║"));
57	    lines.push(scheme.primary(botBar));
58	
59	    // 2. Compute Left Column Content (Conversation Transcript & Thoughts)
60	    const leftLines: string[] = [];
61	    leftLines.push(pc.bold(pc.cyan("── Recent Agent Activity & Thoughts ──")));
62	
63	    const messages = this.agent.getMessages();
64	    const recentMessages = messages.slice(-5);
65	
66	    if (recentMessages.length === 0) {
67	      leftLines.push(pc.dim("No turns executed yet. Type a task in the REPL."));
68	    } else {
69	      for (const msg of recentMessages) {
70	        if (msg.role === "user") {
71	          const text = typeof msg.content === "string" ? msg.content : "[multimodal]";
72	          leftLines.push(pc.bold(pc.green("User: ")) + this.truncate(text, colLeftWidth - 8));
73	        } else if (msg.role === "assistant") {
74	          const text = typeof msg.content === "string" ? msg.content : "";
75	          if (text) {
76	            leftLines.push(pc.bold(pc.magenta("Assistant: ")) + this.truncate(text.replace(/<thought>[\s\S]*?<\/thought>/g, "").trim(), colLeftWidth - 13));
77	          }
78	          if (msg.tool_calls && msg.tool_calls.length > 0) {
79	            for (const tc of msg.tool_calls) {
80	              leftLines.push(pc.dim(`  ⚡ Tool: `) + pc.yellow(tc.function.name));
81	            }
82	          }
83	        } else if (msg.role === "tool") {
84	          const out = typeof msg.content === "string" ? msg.content : "";
85	          leftLines.push(pc.dim(`    ✔ Result: `) + this.truncate(out.replace(/\n/g, " "), colLeftWidth - 16));
86	        }
87	      }
88	    }
89	
90	    // 3. Compute Right Column Content (Workspace Git, Plan, Tokens, Extensibility)
91	    const rightLines: string[] = [];
92	    rightLines.push(pc.bold(pc.cyan("── Project Status & Engine ──")));
93	
94	    // Active Plan
95	    const plan = this.agent.getActivePlan();
96	    rightLines.push(pc.bold(pc.white("Execution Plan:")));
97	    if (plan.length === 0) {
98	      rightLines.push(pc.dim("  (No active milestones defined)"));
99	    } else {
100	      for (let i = 0; i < Math.min(plan.length, 4); i++) {
101	        const p = plan[i];
102	        const icon = p.status === "completed" ? pc.green("✔") : p.status === "in_progress" ? pc.yellow("⏳") : pc.dim("○");
103	        rightLines.push(`  ${icon} ${this.truncate(p.name, colRightWidth - 6)}`);
104	      }
105	    }
106	
107	    rightLines.push("");
108	    rightLines.push(pc.bold(pc.white("Context & Tokens:")));
109	    const tokenStats = this.agent.getTokenStats();
110	    const limit = this.config.contextLimit || 65536;
111	    const total = tokenStats.total;
112	    const pct = Math.min(100, Math.round((total / limit) * 100));
113	    const filled = Math.min(14, Math.round((total / limit) * 14));
114	    const empty = Math.max(0, 14 - filled);
115	    const bar = (pct > 80 ? pc.red : pct > 60 ? pc.yellow : pc.green)("█".repeat(filled)) + pc.dim("░".repeat(empty));
116	    rightLines.push(`  [${bar}] ${pct}% (${total.toLocaleString()} / ${limit.toLocaleString()})`);
117	
118	    rightLines.push("");
119	    rightLines.push(pc.bold(pc.white("Active Subsystems & Identity:")));
120	    rightLines.push(pc.dim(`  • Task ID: `) + pc.cyan(this.app ? this.app.getTaskId() : this.agent.getTaskId()));
121	    const taskState = this.app ? this.app.getTaskState() : null;
122	    const candidateId = taskState?.candidateId || this.agent.getActiveValidationReceipt()?.candidateId;
123	    if (candidateId) {
124	      rightLines.push(pc.dim(`  • Candidate: `) + pc.cyan(candidateId.slice(0, 12)));
125	    }
126	    const receipt = this.app ? this.app.getActiveValidationReceipt() : this.agent.getActiveValidationReceipt();
127	    if (receipt) {
