129	      rightLines.push(pc.dim(`  • Receipt: `) + recStatus);
130	    }
131	    const worktreePath = taskState?.worktreeBinding?.worktreePath;
132	    if (worktreePath) {
133	      rightLines.push(pc.dim(`  • Worktree: `) + pc.cyan(path.basename(worktreePath)));
134	    }
135	    rightLines.push(pc.dim(`  • Theme: `) + pc.cyan(this.themeManager.getThemeName()));
136	    rightLines.push(pc.dim(`  • History: `) + pc.cyan(`${this.agent.getHistoryCount()} messages`));
137	    rightLines.push(pc.dim(`  • Sandbox: `) + pc.cyan(this.config.sandbox ? "Enabled" : "Off"));
138	
139	    // 4. Merge Left and Right Columns side-by-side
140	    const maxContentLines = Math.max(leftLines.length, rightLines.length, 12);
141	    for (let i = 0; i < maxContentLines; i++) {
142	      const left = leftLines[i] || "";
143	      const right = rightLines[i] || "";
144	
