      return deepFreezeTurn(assertTurnResultInvariants({
        ...base, execution: "LIMIT_REACHED", outcome: "NOT_ESTABLISHED", reason: "STEP_LIMIT_REACHED", finalOutputComplete: false,
      }));
    }

