1111	    const toolTurnStarts = source
1112	      .map((message, index) => message.role === "assistant" && message.tool_calls?.length ? index : -1)
1113	      .filter((index) => index >= 0);
1114	    const recentStart = recentToolTurns > 0 && toolTurnStarts.length
1115	      ? toolTurnStarts[Math.max(0, toolTurnStarts.length - recentToolTurns)]
1116	      : source.length;
1117	    const retainedOriginalContent = new Set<number>();
1118	    source.forEach((message, index) => {
1119	      if (normalizeMessageContent(message.content).preserveOriginal) retainedOriginalContent.add(index);
1120	    });
1121	    const retained = source
1122	      .map((message, index) => ({ message, index }))
1123	      .filter(({ message, index }) => index > 0 && index !== currentUserIndex && ((message.role !== "system" && index >= recentStart) || retainedOriginalContent.has(index)));
1124	    const messagesToSummarize = source
1125	      .map((message, index) => ({ message, index }))
1126	      .filter(({ message, index }) => index > 0 && index !== currentUserIndex && (retainedOriginalContent.has(index) || !(index >= recentStart && message.role !== "system")));
1127	    const summary = this.summarizeDiscardedHistory(messagesToSummarize.map(({ message }) => message), detailBudgetChars);
1128	    const compacted: ChatMessage[] = [system];
1129	    if (messagesToSummarize.length) {
1130	      const summaryMessage: ChatMessage = { role: "system", content: summary.content };
1131	      canonicalDurableProvenance.get(this)?.set(summaryMessage, summary.provenance);
1132	      compacted.push(summaryMessage);
1133	    }
1134	    const selected = new Map<number, ChatMessage>();
1135	    for (const item of retained) selected.set(item.index, item.message);
1136	    if (currentUserIndex !== undefined) selected.set(currentUserIndex, source[currentUserIndex]);
1137	    for (const [index, message] of Array.from(selected.entries()).sort((left, right) => left[0] - right[0])) compacted.push(message);
