1141	  private admitContext(step: number, requestId: string): void {
1142	    const contextLimit = this.config.contextLimit || 65536;
1143	    const reserves = this.getContextReserves();
1144	    const original = this.messages;
1145	    let budget = calculateContextBudget(original, this.getEffectiveTools(), contextLimit);
1146	    let compacted = false;
1147	
1148	    if (!isContextAdmissible(budget.totalActiveTokens, contextLimit, reserves.completion, reserves.toolResponse)) {
1149	      compacted = true;
1150	      let accepted = false;
1151	      for (const recentTurns of [2, 1, 0]) {
1152	        for (const detailBudgetChars of [6000, 3000, 1200, 400, 0]) {
1153	          const candidate = this.compactedMessages(original, recentTurns, detailBudgetChars);
1154	          const candidateBudget = calculateContextBudget(candidate, this.getEffectiveTools(), contextLimit);
1155	          if (isContextAdmissible(candidateBudget.totalActiveTokens, contextLimit, reserves.completion, reserves.toolResponse)) {
1156	            this.messages = candidate;
1157	            budget = candidateBudget;
1158	            accepted = true;
1159	            break;
1160	          }
1161	        }
1162	        if (accepted) break;
1163	      }
1164	      if (!accepted) {
1165	        budget = calculateContextBudget(original, this.getEffectiveTools(), contextLimit);
1166	        console.log(`[context_admission] step=${step} request_id=${requestId} state=blocked estimated_tokens=${budget.totalActiveTokens} completion_reserve=${reserves.completion} tool_response_reserve=${reserves.toolResponse} limit=${contextLimit}`);
1167	        throw new ContextBudgetError(budget.totalActiveTokens, reserves.completion, reserves.toolResponse, contextLimit);
1168	      }
1169	    }
1170	
1171	    console.log(`[context_admission] step=${step} request_id=${requestId} state=admitted estimated_tokens=${budget.totalActiveTokens} completion_reserve=${reserves.completion} tool_response_reserve=${reserves.toolResponse} limit=${contextLimit} compacted=${compacted} messages=${this.messages.length}`);
1172	  }
