        if a["role"] != "assistant" or t["role"] != "tool": break
        n += 1; cid = f"call_{n:03d}"
        calls = [dict(tc) for tc in (a.get("tool_calls") or [])]
        if calls: calls[0] = {**calls[0], "id": cid}
