    tc = (a.get("tool_calls") or [{}])[0].get("function", {})
    return f"{tc.get('name','?')} {str(tc.get('arguments',''))[:80]}"

def cap_text(c, cap_tokens):
    """head+tail by chars so the result is ~cap_tokens (4 chars/token)."""
    lim = cap_tokens * 4
    if len(c) <= lim: return c, False
    h = lim // 2
