    ap.add_argument("--layouts", default="L0,L1,L2,L2b,L3u,L3s"); ap.add_argument("--reps", type=int, default=2)
    ap.add_argument("--steps", default="1-30"); ap.add_argument("--model", default="engineering/b0")
