                ev0 = sum(v for k2, v in mt0.items() if k2.startswith("aihost_engine_prompt_tokens_total"))
                row.update(wall_s=round(dt, 3), prompt_tokens=u.get("prompt_tokens"), cached_tokens=(u.get("prompt_tokens_details") or {}).get("cached_tokens"),
                           engine_evaluated_delta=ev - ev0, route=route)
                out.write(json.dumps(row) + "\n"); out.flush()
                print(f"rep{rep} {name:3s} step{step:2d} est={est_total:6d} prompt={row['prompt_tokens']} cached={row['cached_tokens']} wall={dt:6.2f}s", flush=True)
    if out: out.close()

