 *
 * Contract under test (docs/reviews/NEXUS_PARALLEL_DEFECT_INVESTIGATION_2026-10-04.md, D4):
 *  - the turn ends BLOCKED / NOT_ESTABLISHED / CONTEXT_CAPACITY_EXCEEDED, not an exception or UNHANDLED_ERROR
 *  - no over-budget request reaches the gateway
 *  - when no model call happened in the turn, the pending user message is NOT left in history, so retries never accumulate
 *  - when earlier steps of the turn already ran, the existing conversation and tool evidence are kept (nothing is discarded)
 *  - the result states the admission arithmetic, whether a model call occurred, and what happened to the message
 */
import { test, describe } from "node:test";
import assert from "node:assert/strict";
import http from "node:http";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { execSync } from "node:child_process";
import { AutonomousAgent } from "../src/agent.js";
import { ApplicationCore } from "../src/core/app.js";
import { exitCodeForTurn } from "../src/core/turn.js";

interface Gw { url: string; requests: number; close(): Promise<void> }

async function gateway(script: (n: number) => { tool?: { name: string; args: unknown }; text?: string }): Promise<Gw> {
  const gw: Gw = { url: "", requests: 0, close: async () => {} };
  const server = http.createServer((req, res) => {
    let raw = "";
    req.on("data", (c) => (raw += c));
    req.on("end", () => {
      gw.requests++;
      const r = script(gw.requests);
      res.writeHead(200, { "content-type": "text/event-stream" });
      const delta = r.tool
        ? { tool_calls: [{ index: 0, id: `call_${gw.requests}`, type: "function", function: { name: r.tool.name, arguments: JSON.stringify(r.tool.args) } }] }
        : { content: r.text ?? "ok" };
      res.write(`data: ${JSON.stringify({ choices: [{ delta, finish_reason: r.tool ? "tool_calls" : "stop" }] })}\n\ndata: [DONE]\n\n`);
      res.end();
    });
  });
  await new Promise<void>((resolve) => server.listen(0, "127.0.0.1", () => resolve()));
  gw.url = `http://127.0.0.1:${(server.address() as any).port}/v1`;
  gw.close = () => new Promise<void>((resolve) => { server.closeAllConnections(); server.close(() => resolve()); });
  return gw;
}

function repo(files: Record<string, string> = {}): string {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), "nexus-capacity-"));
  fs.writeFileSync(path.join(dir, "base.txt"), "base\n");
  for (const [n, c] of Object.entries(files)) fs.writeFileSync(path.join(dir, n), c);
  execSync("git init -q && git config user.name t && git config user.email t@t.invalid && git add . && git commit -qm base", { cwd: dir, stdio: "ignore" });
