cat > /tmp/dogfood/trail.py <<'EOF'
import json,glob,os,sys
wt=sys.argv[1]
best=None
for f in glob.glob(os.path.expanduser("~/.nexus/sessions/*.json")):
    try: d=json.load(open(f))
    except Exception: continue
    if (d.get("workspace") or "").rstrip("/")==wt.rstrip("/") or (d.get("workspacePath") or "").rstrip("/")==wt.rstrip("/"):
        if not best or d.get("updatedAt","")>best[1].get("updatedAt",""): best=(f,d)
if not best: print("no session found"); sys.exit()
f,d=best; print("session",os.path.basename(f),"status",d.get("status"),"messages",len(d["messages"]))
for m in d["messages"]:
    if m["role"]=="assistant" and m.get("tool_calls"):
        for tc in m["tool_calls"]:
            a=tc["function"]["arguments"]; print("  CALL",tc["function"]["name"],(a[:150]+"…") if len(a)>150 else a)
    elif m["role"]=="assistant" and m.get("content"): print("  SAY ",str(m["content"])[:140].replace("\n"," "))
    elif m["role"]=="tool":
        c=str(m.get("content")); print("   -> ",c[:110].replace("\n"," "))
print("lastTurn:",json.dumps({k:(d.get("lastTurn") or {}).get(k) for k in ("execution","outcome","reason","modelStop")}))
EOF
